export function fichaComponente(p){
 if(!p)return null;
 const r=REGISTROS[p.id]||null;
 const d=detallePieza(p);
 const nombre=nombreAnatomico(p).espanol;
 const original=String(r?.nombreFuente||p.name||'');
 const verificada=fichaAnatomicaIdentificada(original);
 const perfil=grupoMaterialOcular(p);
 const sistema=infoSistema(p.system).name;
 const esVentriculo=r?.clasificacion==='ventriculo-cerebral';
 const grupo=esVentriculo?'Sistema ventricular del encéfalo':sistema;
 const descripcion=verificada?.descripcion||((perfil&&DESCRIPCIONES_OCULARES[perfil])||(d.especifico?d.descripcion:r?.estructuraGeneral||d.descripcion)||'');
 const estructura=verificada?.estructura||(d.especifico?d.estructura:(r?.estructuraGeneral||d.estructura||''));
 const funcion=verificada?.funcion||(d.especifico?d.funcion:(r?.funcionGeneral||d.funcion||''));
 const ubicacion=verificada?.ubicacion||r?.ubicacion||'';
 const lado=r?.lado||'';
 const tipo=perfil?PERFILES_OCULARES[perfil]?.nombre||r?.tipo||d.titulo:r?.tipo||d.titulo;
 const relaciones=verificada?.relaciones||'';
 const nivel=verificada?'ampliada':d.especifico||perfil?'general documentada':'general de categoría';
 const subpieza=/\b(head|lobe|branch|part of|segment|portion|body of)\b/i.test(original);
 const alcance=verificada?(subpieza?'La explicación funcional corresponde al músculo u órgano del que forma parte esta subestructura.':'Síntesis educativa de anatomía general identificada por su nombre.'):'Información orientativa del tipo de estructura; no se dispone de una descripción individual comprobada para esta malla.';
 const datos=[
  `${nombre}.`,
  `Sistema anatómico: ${grupo}.`,
  verificada?.titulo&&verificada.titulo.toLocaleLowerCase('es')!==nombre.toLocaleLowerCase('es')?`Se relaciona con ${verificada.titulo}.`:null,
  descripcion?`Descripción. ${descripcion}`:null,
  ubicacion&&!/sin localizaci[oó]n|no documentada/i.test(ubicacion)?`Ubicación. ${ubicacion}`:null,
  funcion?`Función. ${funcion}`:null,
  estructura&&estructura!==descripcion?`Organización. ${estructura}`:null,
  relaciones?`Relaciones anatómicas. ${relaciones}`:null
 ].filter(Boolean);
 const narracion=datos.join(' ');
 return {
  id:p.id,conceptId:p.conceptId||'',nombre,original,grupo,tipo,
  ubicacion:ubicacion&&!/sin localizaci[oó]n|no documentada/i.test(ubicacion)?ubicacion:'No especificada para esta pieza',
  lado,descripcion,estructura,funcion,relaciones,
  vertices:Number(p.vertexCount)||r?.vertices||0,
  triangulos:Math.floor((Number(p.indexCount)||r?.triangulos*3||0)/3),
  nota:alcance,alcance,nivel,especifico:Boolean(verificada||d.especifico||perfil),
  resumen:verificada?descripcion+' '+funcion:descripcion+' '+(funcion?`Función general: ${funcion}`:''),
  narracion,fuenteIdentificada:!!r,fuentes:verificada?.fuentes||[],temaVerificado:verificada?.titulo||''
 };
}
export function hayFichaComponente(id){return Object.prototype.hasOwnProperty.call(REGISTROS,id);}
export function resumenCobertura(){return {total:CANTIDAD_FICHAS,documentadas:Object.keys(REGISTROS).length};}
